import React, { useEffect, useState } from "react";
import { View, Text, Button, FlatList, ActivityIndicator, ScrollView, Alert } from "react-native";
import { NativeStackScreenProps } from "@react-navigation/native-stack";
import { getCustomerById, getCustomerSummary, getCustomerTransactions } from "../api";
import { Customer, Transaction, CustomerSummary } from "../types";
import { RootStackParamList } from "../../App";

type Props = NativeStackScreenProps<RootStackParamList, "CustomerDetail">;

export default function CustomerDetailScreen({ route, navigation }: Props) {
  const { customerId } = route.params;
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [summary, setSummary] = useState<CustomerSummary | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const unsubscribe = navigation.addListener("focus", fetchData);
    fetchData();
    return unsubscribe;
  }, [navigation]);

  async function fetchData() {
    setLoading(true);
    setError(null);

    try {
      const [customerData, transactionsData, summaryData] = await Promise.all([
        getCustomerById(customerId),
        getCustomerTransactions(customerId),
        getCustomerSummary(customerId),
      ]);
      setCustomer(customerData);
      setTransactions(transactionsData);
      setSummary(summaryData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load customer");
    } finally {
      setLoading(false);
    }
  }

  if (loading) {
    return (
      <View style={{ flex: 1, justifyContent: "center", alignItems: "center" }}>
        <ActivityIndicator />
      </View>
    );
  }

  if (error || !customer) {
    return (
      <View style={{ flex: 1, padding: 16 }}>
        <Text style={{ color: "red" }}>{error || "Customer not found"}</Text>
      </View>
    );
  }

  return (
    <ScrollView style={{ flex: 1, padding: 16 }}>
      <Text style={{ fontSize: 20, fontWeight: "bold" }}>{customer.fullName}</Text>
      <Text style={{ marginTop: 8 }}>{customer.phoneNumber}</Text>
      <Text style={{ marginTop: 4 }}>{customer.address}</Text>
      <Text style={{ marginTop: 4 }}>{customer.notes}</Text>

      {summary ? (
        <View style={{ marginTop: 16, padding: 16, borderWidth: 1, borderColor: "#ddd", borderRadius: 8 }}>
          <Text style={{ fontSize: 16, fontWeight: "600" }}>Summary</Text>
          <Text>Total charges: {summary.summary.totalCharges}</Text>
          <Text>Total payments: {summary.summary.totalPayments}</Text>
          <Text>Total adjustments: {summary.summary.totalAdjustments}</Text>
          <Text style={{ fontWeight: "bold" }}>Balance: {summary.summary.balance}</Text>
        </View>
      ) : null}

      <View style={{ marginTop: 16, gap: 10 }}>
        <Button
          title="Edit customer"
          onPress={() => navigation.navigate("CustomerForm", { customerId: customer.id })}
        />
        <Button
          title="New charge"
          onPress={() => navigation.navigate("TransactionForm", { customerId, initialType: "CHARGE" })}
        />
        <Button
          title="New payment"
          onPress={() => navigation.navigate("TransactionForm", { customerId, initialType: "PAYMENT" })}
        />
        <Button
          title="New adjustment"
          onPress={() => navigation.navigate("TransactionForm", { customerId, initialType: "ADJUSTMENT" })}
        />
      </View>

      <Text style={{ marginTop: 24, fontSize: 18, fontWeight: "600" }}>Transactions</Text>
      <FlatList
        data={transactions}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <View style={{ padding: 12, borderBottomWidth: 1, borderColor: "#eee" }}>
            <Text style={{ fontWeight: "bold" }}>{item.type}</Text>
            <Text>{item.amount}</Text>
            <Text>{new Date(item.date).toLocaleDateString()}</Text>
            {item.description ? <Text>{item.description}</Text> : null}
            {item.paymentMethod ? <Text>{item.paymentMethod}</Text> : null}
            {item.reason ? <Text>{item.reason}</Text> : null}
          </View>
        )}
      />
    </ScrollView>
  );
}
